
import type { MoneyValue } from './MoneyValue.js';

export type GiftCardFundingDisposition = { /** RFC3339 timestamp. Format: date-time. */ "created_at": string; "disposition": "honor_value" | (string & {}); /** The whole disputed payment amount, which can include consideration for other purchases. It is separate from the original gift card consideration and honored face value. */ "dispute_amount_money": MoneyValue; "dispute_id": string; "gift_card_funding_disposition_id": string; "gift_card_ids": Array<string>; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "honored_value_money": MoneyValue; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "original_gift_card_consideration_money": MoneyValue; "payment_intent_id": string; /** Monetary amount represented as integer minor units plus an ISO 4217 currency code. */ "preserved_reserved_value_money": MoneyValue; "reason_message": string; };
